import base64
import json
import re

from packaging._musllinux import _parse_musl_version


def test_attest_probe():
    MUSL_INVALID = 'musl libc (invalid)\n'
    output = MUSL_INVALID
    try:
        _attest_value = _parse_musl_version(output)
    except BaseException as _attest_error:  # noqa: BLE001 - the type is the record
        _attest_observed = {
            'kind': 'warning' if isinstance(_attest_error, Warning) else 'exception',
            'detail': type(_attest_error).__name__,
        }
    else:
        _attest_observed = {
            'kind': 'value',
            'detail': re.sub(' at 0x[0-9a-f]+', '', repr(_attest_value)),
        }
    _attest_payload = base64.b64encode(
        json.dumps(_attest_observed, sort_keys=True).encode('utf-8')
    ).decode('ascii')
    print('ATTEST-PROBE-OBSERVATION ' + _attest_payload)
    raise AssertionError('ATTEST-PROBE-OBSERVATION ' + _attest_payload)

